std::istringstream in("8 3\n1 3 -1 -3 5 3 6 7\n");
std::ostringstream out;
std::streambuf* cout_old = std::cout.rdbuf(out.rdbuf());
solve(in, out);
std::cout.rdbuf(cout_old);
CHECK_EQ(out.str(), std::string("3 3 5 5 6 7\n"));

